import re
from unicodedata import digit


_PATH = re.compile(r"\w+(?:\.\w+)*")
_TOKEN = re.compile(r"[^{}]+|\{\{|\}\}|[{}]")
_MISSING = object()


def _lookup(path, values):
    value = values
    for name in path.split("."):
        if isinstance(value, dict):
            value = value.get(name, _MISSING)
            if value is _MISSING:
                return _MISSING
        elif isinstance(value, (list, tuple)) and name.isdigit():
            index = 0
            for char in name:
                index = index * 10 + digit(char)
                if index >= len(value):
                    return _MISSING
            value = value[index]
        else:
            return _MISSING
    return value


def render(template, values):
    """Fill fields in a single pass, preserving literal text and defaults."""
    parts = []
    pos = 0
    while pos < len(template):
        match = _TOKEN.match(template, pos)
        token = match.group()
        pos = match.end()
        if token in ("{{", "}}"):
            parts.append(token[0])
        elif token == "}":
            raise ValueError("Unmatched closing brace")
        elif token == "{":
            end = template.find("}", pos)
            if end < 0 or "{" in template[pos:end]:
                raise ValueError("Malformed field")
            path, separator, default = template[pos:end].partition("|")
            path = path.strip()
            if not _PATH.fullmatch(path):
                raise ValueError("Invalid field path")
            value = _lookup(path, values)
            if value is _MISSING:
                if not separator:
                    raise KeyError(path)
                parts.append(default)
            elif value is None:
                parts.append("")
            elif isinstance(value, bool):
                parts.append(str(value).lower())
            else:
                parts.append(str(value))
            pos = end + 1
        else:
            parts.append(token)
    return "".join(parts)
